style.css:
@-moz-document domain("youtube.com") {
/* GLOW RIOT - SELECTED CATEGORY BUTTONS */

yt-chip-cloud-chip-renderer[chip-style="STYLE_HOME_FILTER"][selected] #chip-container,
yt-chip-cloud-chip-renderer #chip-container[aria-selected="true"] {
  background: #861bdb !important;
  color: #ffffff !important;
  border: 2px solid #ff45ce !important;
  box-shadow: 0 0 12px rgba(255, 69, 206, 0.8) !important;
}

/* GLOW RIOT - SEARCH RESULT CHANNEL NAMES */

ytd-video-renderer #channel-name,
ytd-video-renderer #channel-name a,
ytd-channel-name a,
yt-lockup-view-model a[href^="/@"],
yt-lockup-view-model a[href^="/channel/"] {
  color: #ff4dcc !important;
  -webkit-text-fill-color: #ff4dcc !important;
  text-shadow: 0 0 6px rgba(255, 20, 147, 0.55) !important;
}

/* GLOW RIOT - SEARCH RESULT METADATA */

ytd-video-renderer #metadata-line,
ytd-video-renderer .inline-metadata-item,
ytd-video-renderer #metadata,
yt-lockup-view-model .ytContentMetadataViewModelMetadataText,
yt-lockup-view-model .yt-content-metadata-view-model__metadata-text {
  color: #d98aff !important;
  -webkit-text-fill-color: #d98aff !important;
  text-shadow: 0 0 4px rgba(204, 102, 255, 0.4) !important;
}
}
